  FT["PH-H8859"] = {"id":"PH-H8859","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10407_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Ivisan市","en":"An Act Converting the Roxas City - Cagay - Sibaguan - Balijuagan - Cudian - Ivisan Provincial Road in Roxas City and the Municipality of Ivisan, Province of Capiz into a National Road and Providing Funds Therefor","orig":"An Act Converting the Roxas City - Cagay - Sibaguan - Balijuagan - Cudian - Ivisan Provincial Road in Roxas City and the Municipality of Ivisan, Province of Capiz into a National Road and Providing Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10407","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10407_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8859-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The RoxasCity – Cagay – Sibaguan – Balijuagan – Cudian – Ivisan Provincial Road in Roxas City and the Municipality of Ivisan, Province of Capiz is hereby converted into a national road under the jurisdiction and supervision of the Department of Public Works and Highways."}},{"id":"PH-H8859-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Public Works and Highways shah include in the Department’s program the improvement, repair and maintenance of the said road, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8859-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p126"};
  FT["PH-H8860"] = {"id":"PH-H8860","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10408_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定将马尼拉大都会巴伦苏埃拉市Pasolo至Rincon公路改设为国道并为此拨款的法案","en":"An Act Providing for the Conversion of Pasolo to Rincon Road in the City of Valenzuela, Metro Manila into a National Road and Appropriating Funds Therefor","orig":"An Act Providing for the Conversion of Pasolo to Rincon Road in the City of Valenzuela, Metro Manila into a National Road and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10408","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10408_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8860-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Pasolo to Rincon Road in the City of Valenzuela, Metro Manila is hereby converted into a national road."}},{"id":"PH-H8860-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Public Works and Highways shall include in the Department’s program the improvement, repair and maintenance of the said road, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8860-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p126","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Conversion of Pasolo to Rincon Road in the City of Valenzuela, Metro Manila into a National Road and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8861"] = {"id":"PH-H8861","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10409_2013.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"宣布比利兰省为旅游开发区（TDA）并为其提供资金的法案","en":"An Act Declaring the Province of Biliran as a Tourism Development Area (TDA) and Providing Funds Therefor","orig":"An Act Declaring the Province of Biliran as a Tourism Development Area (TDA) and Providing Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10409","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-19","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10409_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8861-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. – This Act shall be known as \"An Act Declaring the Province of Biliran as a Tourism Development Area (TDA)\"."}},{"id":"PH-H8861-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. – It is hereby declared the policy of the State to promote a tourism industry that is ecologically sustainable, responsible, participative, culturally sensitive, economically viable and equitable for local communities. In so doing, the State shall ensure the full implementation of this Act, support the establishment of Tourism Enterprise Zones (TEZ) and the mobilization of resources for the institutional mechanisms herein established to attract and focus investment on specific geographic areas within the TDA."}},{"id":"PH-H8861-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Scope and Coverage. – The TDAs in Biliran hereby include, but not limited to, the following municipalities endowed with natural beauty and historic significance:\nThe Higatangan Island, herein, within the Municipality of Naval in the Province of Biliran, with coordinates beginning at a point marked cor \"1″ northing 1280743 and easting 636564 and ending at a point marked cor \"90″ northing 1280647 and easting 636599 covers an area of 487.46 hectares.\nThe Sambawan Island, herein, within the Municipality of Maripipi in the Province of Biliran, with coordinates beginning at a point marked cor \"1″ northing 1300284 and easting 637845.3 and ending at a point marked cor \"8″ northing 1300269 and easting 637830 covers an area of 1.4 hectares.\nThe Mangrove Area of Looc known as the Cabucgayan Boardwalk, herein, within the Municipality of Cabucgayan in the Province of Biliran, with coordinates beginning at a point marked cor \"1″ northing 1269357 and easting 668319 and ending at a point marked cor \"7″ northing 1269263 and easting 668235.5 covers an area of 4.73 hectares.\nThe Casabangan Falls, herein, within the Municipality of Cabucgayan in the Province of Biliran, with coordinates beginning at a point marked cor \"1″ northing 1270896 and easting 666847.9 and ending at a point marked cor \"9″ northing 1270897 and easting 666830.0 covers an area of 0.18 hectares.\nThe Tinago Falls, herein, within the Municipality of Caibiran in the Province of Biliran, with coordinates beginning at a point marked cor \"1″ northing 1280986 and easting 666353.4 and ending at a point marked cor \"8″ northing 1280947 and easting 666408 covers an area of 0.46 hectares.\nThe Bagongbong Falls, herein, within the Municipality of Almeria in the Province of Biliran, with coordinates beginning at a point marked cor \"1″ northing 1286258 and easting 652825.8 and ending at a point marked cor \"8″ northing 1286240 and easting 652815.6 covers an area of 0.21 hectares.\nThe technical descriptions provided in this Act will be subject to ground survey and verification to be conducted by the Department of Environment and Natural Resources-NAMRIA."}},{"id":"PH-H8861-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Tourism Development Plan of Biliran. – The Tourism Development Plan of the Province of Biliran shall be incorporated in the Department of Tourism’s (DOT) overall National Tourism Development Plan (NTDP) and be jointly implemented with the Local Government and Provincial Tourism Council of Biliran taking into consideration Republic Act No. 7586, otherwise known as \"National Integrated Protected Areas System Act of 1992″, and its implementing rules and regulations."}},{"id":"PH-H8861-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Biliran Tourism Development Trust Fund. – There is hereby established a trust fund under this Act to be known as the Biliran Tourism Development Trust Fund for purposes of financing projects which shall enhance tourism in the Province of Biliran. The Trust Fund shall be administered by a Trust Fund Administrator under the Provincial Tourism Council of Biliran. Income shall be derived from fees from visitors/tourists, fees from permitted sale and export of flora and fauna and other resources from the province, proceeds from the registration and lease of multiple-use areas, including tourism concessions, fees, proceeds, and contributions from industries and facilities directly benefiting the province.\nThe Trust Fund may be augmented by grants and donations, endowment from various sources, domestic or foreign entities and individuals, for purposes related to their functions: Provided, That disbursements therefrom shall be in accordance with existing accounting and auditing rules and regulations: Provided, further, That the Trust Fund shall not be used to cover personal services expenditures."}},{"id":"PH-H8861-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Implementing Rules and Regulations. – The Secretary of the DOT together with the Secretary of the Department of Environment and Natural Resources (DENR) in consultation with the stakeholders shall promulgate the necessary rules and regulations for the proper implementation of this Act."}},{"id":"PH-H8861-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Appropriations. – The Secretary of the DOT and the Secretary of the DENR shall immediately include in the DOT and the DENR’s program the implementation of this Act, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8861-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Repealing Clause. – The provision of Proclamation No. 1801, VIII(2) inconsistent with the provision of this Act is hereby amended accordingly."}},{"id":"PH-H8861-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Separability Clause. – If any part or section of this Act is declared unconstitutional, any other provisions not otherwise affected thereby shall remain in full force and effect."}},{"id":"PH-H8861-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in a national newspaper of general circulation."}}],"pack":"ph-p126","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring the Province of Biliran as a Tourism Development Area (TDA) and Providing Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8862"] = {"id":"PH-H8862","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10410_2013.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"承认零至八岁为教育发展第一关键阶段并加强幼儿保育与发展系统、为此拨款并为其他目的法案","en":"An Act Recognizing the Age From Zero (0) to Eight (8) Years as the First Crucial Stage of Educational Development and Strengthening the Early Childhood Care and Development System, Appropriating Funds Therefor and for Other Purposes","orig":"An Act Recognizing the Age From Zero (0) to Eight (8) Years as the First Crucial Stage of Educational Development and Strengthening the Early Childhood Care and Development System, Appropriating Funds Therefor and for Other Purposes"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 10410","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-26","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10410_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8862-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. – This Act shall be known as the \"Early Years Act (EYA) of 2013″."}},{"id":"PH-H8862-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. – It is hereby declared the policy of the State to promote the rights of children to survival, development and special protection with full recognition of the nature of childhood and as well as the need to provide developmentally appropriate experiences to address their needs; and to support parents in their roles as primary caregivers and as their children’s first teachers. Further, the State hereby recognizes the age from zero (0) to eight (8) years as the first crucial stage of educational development of which the age from zero (0) to four (4) years shall be the responsibility of the Early Childhood Care and Development (ECCD) Council. Therefore, the responsibility to help develop children in the formative years between age five (5) to eight (8) years shall be with the Department of Education (DepED).\nThe State shall institutionalize a National System for Early Childhood Care and Development (ECCD) that is comprehensive, integrative and sustainable, that involves multisectoral and interagency collaboration at the national and local levels among government; among service providers, families and communities, and among the public and private sectors, nongovernment organizations; professional associations and academic institutions.\nThe System shall promote the inclusion of children with special needs, provide for reasonable accommodation and accessible environments for children with disabilities and advocate respect for cultural and linguistic diversity, including the use of Filipino Sign Language as the visual language of the deaf community. It shall be anchored on complementary strategies for ECCD that include service delivery for children from age zero (0) to four (4) years, educating parents and caregivers, encouraging the active involvement of parents and communities in ECCD programs, raising awareness about the important efforts that improve the quality of life for young children and families."}},{"id":"PH-H8862-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Objectives. – The National ECCD System shall pursue the following objectives:\n(a) To achieve improved infant and child survival rates by ensuring that adequate health and nutrition programs are accessible to young children and their parents, from the prenatal period throughout the early childhood years;\n(b) To enhance the physical-motor, socio-emotional, cognitive, language, psychological and spiritual development of young children;\n(c) To facilitate a smooth transition from care and education provided at home to community or school-based setting and to kindergarten;\n(d) To ensure that young children are adequately prepared for the formal learning system that begins at kindergarten;\n(e) To establish an efficient system for early identification, prevention, referral and intervention for the wide range of children with special needs from age zero (0) to four (4) years;\n(f) To upgrade and update the capabilities of service providers and their supervisors to comply with quality standards for various ECCD programs;\n(g) To reinforce the role of parents and other caregivers as the primary caregivers and educators of their children especially from age zero (0) to four (4) years;\n(h) To enhance and sustain the efforts of communities to promote ECCD programs and ensure that special support is provided for poor, disadvantaged and linguistic minority communities;\n(i) To improve the quality standards of public and private ECCD programs through, but not limited to, a registration and credential system for ECCD service providers and facilities,\n(j) To ensure that the education of persons, and in particular children, who are blind, deaf or deafblind, are conducted in the most appropriate languages, modes and means of communication for the individual, and in environments which maximize academic and social development; and\n(k) To employ teachers, including teachers with disabilities, who are qualified in sign language and/or braille, and to train professionals and staff who work at all levels of education."}},{"id":"PH-H8862-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Definitions. – The following terms are defined as follows:\n(a) Early Childhood Care and Development (ECCD) System shall refer to the full range of health, nutrition, early education and social services development programs that provide for the basic holistic needs of young children from age zero (0) to four (4) years; and to promote their optimum growth and development.\nThese programs shall include:\n(1) Center-based programs, such as the day care service established under Republic Act No. 6972, otherwise known as the \"Barangay – Level Total Development and Protection of Children Act\", and hereinafter referred to as the child development service, community or church-based early childhood education programs initiated by nongovernment organizations or people’s organizations, workplace-related child care and education programs, child-minding centers, health centers and stations; and\n(2) Home-based programs, such as the neighborhood-based play groups, family child care programs, parent education and home visiting programs.\n(b) ECCD Service Providers shall include the various professionals, paraprofessionals and volunteer caregivers who are directly responsible for the care and education of young children from age zero (0) to four (4) years through the various centers and home-based programs. They shall include, but shall not be limited to, day care workers hereinafter referred to as child development workers, child development teachers, teacher-aides, rural health midwives, social workers, community health workers, barangay nutrition scholars, parent effectiveness service volunteers, and family day care providers.\n(c) ECCD Curriculum shall refer to the developmentally-appropriate educational objectives and practices, programs of activities, organized learning experiences, recommended learning materials and appropriate assessment for children from age zero (0) to four (4) years that are implemented by service providers through center and home-based programs. It shall consist of national program goals and guidelines, instructional objectives, and content outlines that are age-appropriate, individually appropriate and culturally relevant.\n(d) Parent Education shall refer to the various formal and alternative means of providing parents with information, skills, and support systems to assist them in their roles as their children’s primary caregivers and educators. These include public and private parent education programs linked to center, home and media-based child care and education programs."}},{"id":"PH-H8862-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"System Framework and Components. – The ECCD System shall ensure that the National ECCD Program is implemented in accordance with quality standards for accreditation and for this purpose there shall be established a National ECCD Monitoring and Evaluation Framework. The ECCD System shall include the following components:\n(a) ECCD Curriculum. – The curriculum shall focus on children’s total development and take into account age, individual and socio-cultural appropriateness. It shall promote the delivery of complementary and integrative services for health, nutrition, early childhood education, sanitation and cultural activities. It shall use the child’s first language as the medium of instruction;\n(b) Parent Education and Involvement, Advocacy and Mobilization of Communities. – This component shall harness and develop parents’ strengths as providers of ECCD programs at home, as active partners of other stakeholders, as advocates for community concerns that affect children, and as pillars of support for local and national ECCD programs through community organization efforts;\n(c) Human Resource Development Program. – The program shall establish mechanisms for the systematic professionalization of ECCD service providers through enrolment in educational program in site-based or distance education modes, through pre-service or in-service training including continuing education programs, whereby a registration and credential system shall be developed in the ECCD System; and\n(d) ECCD Management. – This component shall consist of a continuing process of planning, implementation, supervision, financial management, monitoring, evaluation and reporting to persons concerned and shall encourage the active involvement of and build the capabilities of service providers, parents and local government officials to sustain the program."}},{"id":"PH-H8862-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Expanding the ECCD System. – The National ECCD System shall henceforth apply to all provinces, cities, municipalities and barangays as may be determined by the ECCD Council to achieve universal ECCD coverage for all children from age zero (0) to four (4) years."}},{"id":"PH-H8862-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Implementing Arrangements and Operational Structures. – The implementation of the National ECCD System shall be the responsibility of the ECCD Council.\n(a) Responsibilities of the ECCD Council. – The ECCD Council shall he responsible for establishing national standards, developing policies and programs, ensuring compliance thereof providing technical assistance and support to the ECCD service providers in consultation with coordinating committees at the provincial, city, municipal and barangay levels.\nThe Department of Education (DepED), the Department of Social Welfare and Development (DSWD), the Department of Health (DOH), the National Nutrition Council (NNC) and the Union of Local Authorities of the Philippines (HEAP) shall meet in an annual workshop to prepare work and financial plans that will coordinate their technical assistance and support for the National ECCD Program. They shall observe existing implementing guidelines that ensure consistency in integrated service delivery within the National ECCD System, as follows:\n(1) The DepED shall recognize the National ECCD Program as the foundation of the learning continuum and shall promote it for all children from age zero (0) to four (4) years; and\n(2) The DepED, the DSWD, the DOH and the NNC shall provide continuing professional development program support, supplementary learning materials, reference materials, supplemental nutrition and health care services.\n(b) Responsibilities of Local Government Units. – Local government units (LGUs) shall include allocations from their Special Education Fund (SEF) and Gender and Development (GAD) Fund in addition to other local funds to be utilized for the following purposes:\n(1) Support the implementation of their ECCD Program;\n(2) Organize and support parent cooperatives to establish community-based ECCD programs;\n(3) Provide counterpart funds for the continuing professional development of their ECCD public service providers; and\n(4) Provide the facilities for the conduct of their ECCD Program.\n(c) Responsibilities of Families and Communities. Families and communities shall support the local ECCD programs by participating in various community-based projects such as, but not limited to, health, nutrition, social development and early childhood education projects for the overall development of their children from age zero (0) to four (4) years."}},{"id":"PH-H8862-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Strengthening the ECCD Council. – The ECCD Council shall be strengthened to ensure the State’s focus on building a strong foundation for the development and learning of children during the early years from age zero (0) to four (4) years, to support the full range of health, nutrition, early education and social development programs for the child’s holistic development and ensure sustained interagency and multisectoral collaboration. The Council shall he attached to the DepED."}},{"id":"PH-H8862-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Organization of the ECCD Council. – The ECCD Council shall be composed of the following.\n(a) ECCD Governing Board. – The ECCD Governing Board shall he composed of:\n(1) Secretary of the DepED, as ex officio Chairperson;\n(2) Executive Director of the ECCD Council, as Vice Chairperson;\n(3) Secretary of the DSWD, as member;\n(4) Secretary of the DOH, as member;\n(5) Executive Director of the NNC, as member;\n(6) President of the ULAP, as member; and\n(7) One (1) private individual who is an ECCD practitioner and expert shall be appointed by the President upon the recommendation of the Board, as member.\nThe Board shall meet once a month or upon the call of the Chairperson or three (3) members of the Board.\n(b) Council Secretariat. – There shall be established an ECCD Council Secretariat to be beaded by an Executive Director. The Secretariat shall provide support services for the coordination and monitoring of the implementation of policies and plans formulated by the Council subject to the Compensation and Position Classification System and other existing civil service rules and regulations."}},{"id":"PH-H8862-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Functions of the ECCD Council. – The ECCD Council shall carry out the objectives of the National ECCD System by performing the following functions:\n(a) Promulgate policies and implement guidelines for ECCD programs in consultation with stakeholders, including the regional level when appropriate, consistent with the national policy and program frameworks as defined in this Act;\n(b) Establish ECCD program standards that reflect developmentally appropriate practices for ECCD programs, which shall interface with the kindergarten curriculum of the DepED;\n(c) Develop a national system for the recruitment, registration, accreditation, continuing education and equivalency, and credential system of ECCD service providers, supervisors and administrators to improve and professionalize the ECCD sector and upgrade quality standards of public and private ECCD programs;\n(d) Develop a national system of awards and recognition to deserving ECCD program implementers and service providers;\n(e) Promote, encourage and coordinate the various ECCD programs of the DepED, the DSWD, the DOH and the NNC, and monitor the delivery of services to the ECCD program beneficiaries nationwide;\n(f) Evaluate and assess the impact and outcome of various ECCD programs nationwide through an effective information system;\n(g) Develop a national system for early identification, screening and surveillance of young children from age zero (0) to four (4) years;\n(h) Develop various support mechanisms that maximize public and private resources for implementing ECCD programs, giving priority to the needy and high risk children from poor communities;\n(i) Provide funds to poor and disadvantaged communities for the establishment and expansion of public ECCD programs, improvement of physical facilities and for hiring of ECCD service providers;\n(j) Promote and encourage private sector initiatives for the establishment of ECCD programs;\n(k) Provide guidelines for the conduct of solicitations from local and international civic organizations, and request private foundations to supplement available resources; and\n(l) Perform such other functions as the ECCD Council may deem necessary."}},{"id":"PH-H8862-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Appropriations. – The amount needed for the initial implementation of this Act shall be charged against the current year’s appropriations of the DepED, the DSWD, the DOH and the NNC for the purpose. Thereafter, such sums as may be necessary for the continued implementation of this Act shall he included in the annual General Appropriations Act (GAA).\nIn addition, the Philippine Amusement and Gaining Corporation shall contribute an amount of Five hundred million pesos (P500,000,000.00) per year for five (5) years from its gross income to fund the establishment of National Child Development Centers and the conversion of existing Day Care Centers into Child Development Centers in various LGUs upon approval of this Act. Said amount shall he directly remitted in four (4) quarterly installments to a special account of the ECCD Council."}},{"id":"PH-H8862-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Financing ECCD Programs. – ECCD programs shall be financed through a combination of public and private funds. All public ECCD program providers shall prioritize children from age zero (0) to four (4) years horn families who are in greatest need and who can least afford private ECCD programs.\n(a) Financial and Technical Support. – The DepED, the DSWD and the DOH shall support the implementation of the National ECCD System by providing financial and technical support packages to ECCD programs.\n(b) Other Forms of Support for ECCD Programs. – LGUs shall be encouraged to support public ECCD programs in their respective localities. Additional funds may be generated from intergovernmental donors and government financial institutions to support the public programs including the urban poor.\nThere shall be established a fund for an ECCD Program Contracting Scheme with accredited private providers at the community levels.\n(c) Fees and Contributions. – Fees and contributions collected for both public and private ECCD programs shall be monitored by the ECCD Council to ensure that these are affordable and within reasonable limits. Families are encouraged to contribute their time and services to support the ECCD programs."}},{"id":"PH-H8862-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Annual Report. – The ECCD Council shall, at the close of each calendar year, submit annual physical and financial reports to Congress, giving a detailed account of its proceedings and accomplishments during the year, making recommendations for the adoption of measures that will improve the National ECCD System and ensuring achievement of universal coverage of ECCD benefits to all children from age zero (0) to four (4) years, within a period of five (5) years."}},{"id":"PH-H8862-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Implementing Rules and Regulations. – The ECCD Council, in consultation with appropriate government agencies and nongovernment organizations, shall formulate and issue the necessary rules and regulations within sixty (60) days after the effectivity of this Act."}},{"id":"PH-H8862-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repealing Clause. – Republic Act No. 8980, otherwise known as \"An Act Promulgating A Comprehensive Policy And A National System For Early Childhood Care And Development (ECCD), Providing Funds Therefor And For Other Purposes\", is hereby repealed.\nAll laws, decrees, executive orders, presidential proclamations, rules and regulations or parts thereof contrary to or inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H8862-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Separability Clause. – If, for any reason, any portion of this Act shall be declared unconstitutional, other parts or provisions hereof which are not affected shall continue to be in full force and effect."}},{"id":"PH-H8862-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in at least two (2) newspapers of general circulation."}}],"pack":"ph-p126","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Recognizing the Age From Zero (0) to Eight (8) Years as the First Crucial Stage of Educational Development and Strengthening the Early Childhood Care and Development System, Appropriating Funds Therefor and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8863"] = {"id":"PH-H8863","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10411_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定将连接莱特省与南莱特省的Abuyog至Silago公路改设为国道并为其维护与改善提供资金的法案","en":"An Act Providing for the Conversion of the Abuyog - Silago Road Connecting the Provinces of Leyte and Southern Leyte into a National Road and Providing Funds for the Maintenance and Improvement Thereon","orig":"An Act Providing for the Conversion of the Abuyog - Silago Road Connecting the Provinces of Leyte and Southern Leyte into a National Road and Providing Funds for the Maintenance and Improvement Thereon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10411","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-26","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10411_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8863-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provincial road known as the Abuyog – Silago Road, connecting the provinces of Leyte and Southern Leyte, which has a length of forty-four (44) kilometers, is hereby converted into a national road."}},{"id":"PH-H8863-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Public Works and Highways shall include in the Department’s program the improvement, repair and maintenance of the said road, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8863-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p126","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Conversion of the Abuyog - Silago Road Connecting the Provinces of Leyte and Southern Leyte into a National Road and Providing Funds for the Maintenance and Improvement Thereon","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
