  FT["PH-H8866"] = {"id":"PH-H8866","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10414_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将打拉市与打拉省Victoria市镇的Tarlac市至新怡诗夏Guimba（经Victoria）公路改设为国道并为此提供资金的法案","en":"An Act Converting the Tarlac City - Guimba, Nueva Ecija Road Via Victoria Road in the City of Tarlac and the Municipality of Victoria Province of Tarlac into a National Road and Providing Funds Therefor","orig":"An Act Converting the Tarlac City - Guimba, Nueva Ecija Road Via Victoria Road in the City of Tarlac and the Municipality of Victoria Province of Tarlac into a National Road and Providing Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10414","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-26","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10414_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8866-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The 22.729-kilometer Tarlac City – Guimba, Nueva Ecija Road via Victoria Road in the City of Tarlac and the Municipality of Victoria, Province of Tarlac is hereby converted into a national road under the jurisdiction and supervision of the Department of Public Works and Highways."}},{"id":"PH-H8866-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Public Works and Highways shall include in the Department’s program the improvement, repair and maintenance of the said road, the funding of which shall be included m the annual General Appropriations Act."}},{"id":"PH-H8866-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p126","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Tarlac City - Guimba, Nueva Ecija Road Via Victoria Road in the City of Tarlac and the Municipality of Victoria Province of Tarlac into a National Road and Providing Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8867"] = {"id":"PH-H8867","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10415_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将马里基纳市Kalumpang与San Roque描笼涯的N. Roxas街改设为国道并为此拨款的法案","en":"An Act Converting N. Roxas Street in Barangays Kalumpang and San Roque in the City of Marikina into a National Road and Appropriating Funds Therefor","orig":"An Act Converting N. Roxas Street in Barangays Kalumpang and San Roque in the City of Marikina into a National Road and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 10415","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-26","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10415_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8867-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"N. Roxas Street in Barangays Kalumpang and San Roque in the City of Marikina is hereby converted into a national road."}},{"id":"PH-H8867-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Public Works and Highways shall include in the Department’s program the improvement, repair and maintenance of the said road, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8867-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p126","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting N. Roxas Street in Barangays Kalumpang and San Roque in the City of Marikina into a National Road and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8868"] = {"id":"PH-H8868","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10416_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将伊洛伊洛市La Paz的Jereos街改设为国道并为此拨款的法案","en":"An Act Converting the Jereos Street in La Paz, Iloilo City into a National Road and Appropriating Funds Therefor","orig":"An Act Converting the Jereos Street in La Paz, Iloilo City into a National Road and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10416","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-26","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10416_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8868-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Jereos Street in La Paz, Iloilo City is hereby converted into a national road under the supervision of the Department of Public Works and Highways."}},{"id":"PH-H8868-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Public Works and Highways shall include in the Department’s program the improvement, repair and maintenance of the said road, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8868-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in a national newspaper of general circulation."}}],"pack":"ph-p126","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Jereos Street in La Paz, Iloilo City into a National Road and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
