  FT["PH-H8877"] = {"id":"PH-H8877","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10425_2013.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将南苏里高省 Hinatuan 市镇 Loyola 描笼涯的 Tagasaka 国立中学附属校分离，改设为独立的 Loyola 国立中学，并为此拨款","en":"An Act Separating the Tagasaka National High School - Loyola Annex in Barangay Loyola, Municipality of Hinatuan, Province of Surigao Del Sur From the Tagasaka National High School, Converting It into an Independent National High School to be Known as Loyola National High School and Appropriating Funds Therefor","orig":"An Act Separating the Tagasaka National High School - Loyola Annex in Barangay Loyola, Municipality of Hinatuan, Province of Surigao Del Sur From the Tagasaka National High School, Converting It into an Independent National High School to be Known as Loyola National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10425","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-04-08","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10425_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8877-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into an Independent National High School. — The Tagasaka National High School — Loyola Annex in Barangay Loyola, Municipality of Hinatuan, Province of Surigao del Sur is hereby separated from the Tagasaka National High School and converted into an independent national high school to be known as Loyola National High School."}},{"id":"PH-H8877-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. — All personnel, assets, liabilities and records of the Tagasaka National High School — Loyola Annex are hereby transferred to and absorbed by the Loyola National High School."}},{"id":"PH-H8877-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. — The Secretary of Education shall immediately include in the Department’s program the operationalization of the Loyola National High School, the initial funding of which shall be charged against the current year’s appropriation of the Tagasaka National High School – Loyola Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8877-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. — The Secretary of Education shall issue rules and regulations that may be necessary to carry out. the purpose of this Act."}},{"id":"PH-H8877-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectively . — This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p126","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Tagasaka National High School - Loyola Annex in Barangay Loyola, Municipality of Hinatuan, Province of Surigao Del Sur From the Tagasaka National High School, Converting It into an Independent National High School to be Known as Loyola National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8878"] = {"id":"PH-H8878","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10426_2013.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Minglanilla市","en":"An Act Establishing a National High School in Barangay Tungkil, Municipality of Minglanilla, Province of Cebu to be Known as Tungkil National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Tungkil, Municipality of Minglanilla, Province of Cebu to be Known as Tungkil National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10426","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-04-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10426_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8878-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Establishment of a National High School. — There is hereby established, under the supervision of the Department of Education, a national high school in Barangay Tungkil, Municipality of Minglanilla, Province of Cebu to be known as Tungkil National High School."}},{"id":"PH-H8878-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Appropriations. — The Secretary of Education shall immediately include in the Department’s program the operationalization of the Tungkil National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8878-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementation. — The Secretary of Education shall issue rules and regulations that may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8878-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity. — This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p126"};
