  FT["PH-H8902"] = {"id":"PH-H8902","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10450_2013.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将拉古纳省 San Pablo 市 Sto. Angel 描笼涯的 San Pablo 市国立中学的 Sto. Angel 附属校分离，改设为独立的同名国立中学，并为此拨款","en":"An Act Separating the San Pablo City National High School - Sto. Angel Annex in Barangay Sto. Angel, City of San Pablo, Province of Laguna From the San Pablo City National High School, Converting It into an Independent National High School to be Known as Sto. Angel National High School and Appropriating Funds Therefor","orig":"An Act Separating the San Pablo City National High School - Sto. Angel Annex in Barangay Sto. Angel, City of San Pablo, Province of Laguna From the San Pablo City National High School, Converting It into an Independent National High School to be Known as Sto. Angel National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10450","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-04-08","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10450_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8902-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into a National High School. – The San Pablo City National High School – Sto. Angel Annex in Barangay Sto. Angel, City of San Pablo, Province of Laguna is hereby separated from the San Pablo City National High School and converted into an independent national high school to be known as Sto. Angel National High School."}},{"id":"PH-H8902-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. – All personnel, assets, liabilities and records of the San Pablo City National High School – Sto. Angel Annex are hereby transferred to and absorbed by the Sto. Angel National High School."}},{"id":"PH-H8902-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. – The Secretary of Education shall immediately include in the Department’s program the operationalization of the Sto. Angel National High School, the initial funding of which shall be charged against the current year’s appropriations of the San Pablo City National High School – Sto. Angel Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8902-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. – The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8902-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication is the Official Gazette."}}],"pack":"ph-p126","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the San Pablo City National High School - Sto. Angel Annex in Barangay Sto. Angel, City of San Pablo, Province of Laguna From the San Pablo City National High School, Converting It into an Independent National High School to be Known as Sto. Angel National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8903"] = {"id":"PH-H8903","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10451_2013.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"在南甘马粦省设立 Bikol 植物园并为其他目的法案","en":"An Act to Establish the Bikol Botanical Garden in the Province of Camarines Sur and for Other Purposes","orig":"An Act to Establish the Bikol Botanical Garden in the Province of Camarines Sur and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10451","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-04-08","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10451_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8903-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established, within the territorial jurisdiction of the Province of Camarines Sur, a botanical garden to be known as the \"Bikol Botanical Garden\". It shall be located in a portion of Mt. Isarog Natural Park within the Municipality of Pili and occupy an area of at least twenty-five (25) hectares to be determined and delineated by the Department of Environment and Natural Resources (DENR) and its faculties shall be built within landscaped spaces in order to create a park-like recreational environment dedicated to botanic research, experimental planting, collection of study specimen, and the teaching and dissemination of botanic knowledge."}},{"id":"PH-H8903-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Bikol Botanical Garden shall have open-air plantings, living plant collections housed in greenhouses either for conservation, teaching or seasonal public display, and herbarium houses for specimens.\nTo the extent practicable as space and technical requirements may allow, the Bikol Botanical Garden may have an arboretum for trees and shrubs; a bamboo setum, pinetum; medicinal plants setum; flowering and ornamental plants setum; aquatic plants setum; palm setum; fernery and orchidarium.\nThe facilities shall be built within a five (5)-year period, depending upon the availability of funds provided by the provincial government of Camarines Sur, national government assistance, and donations and grants from local or foreign sources.\nSatellite gardens may be established elsewhere in a municipality or city within the Province of Camarines Sur, either in an urban or rural setting or both, depending upon the type of soil, topography or climatic conditions required to cultivate or maintain plants intended or suitable for such satellite gardens, and depending upon such appropriate cooperative arrangements as may be agreed upon with the other local governments within the Province of Camarines Sur."}},{"id":"PH-H8903-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The buildings for its officials and staff, the library, and facilities for conferences, seminars, workshops and audio-visual presentations shall be built within a three (3)-year period."}},{"id":"PH-H8903-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Bikol Botanical Garden shall endeavor to maintain a system for the classification of plants for various utilitarian purposes; adopt a program for botanical expeditions to augment its collections; undertake studies and experiments on the commercial cultivation of otherwise wild species of certain plants, arrange for exchanges with other botanical gardens or collectors of plant samples or specimens it may have or with other plants or specimens it seeks to have; cultivate medicinal plants found in the Bicol Region or elsewhere; and establish linkages with agricultural schools and other institutions interested in botanical science."}},{"id":"PH-H8903-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The provincial government of Camarines Sur shall, by purchase or expropriation or by grants from the national government or through donation from other governmental or private philanthropic sources, provide or arrange to provide the lands suitable for establishing the Bikol Botanical Garden and any satellite gardens referred to in this Act.\nThe provincial government of Camarines Sur shall provide the necessary capital outlays and operating expenses required to maintain the botanical garden to be established under this Act."}},{"id":"PH-H8903-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"In the implementation of this Act, the DENR and other agencies of the national government shall extend technical assistance to the provincial government of Camarines Sur."}},{"id":"PH-H8903-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p126","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Establish the Bikol Botanical Garden in the Province of Camarines Sur and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8904"] = {"id":"PH-H8904","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10452_2013.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"在卡加延-德奥罗市 3,000 公顷公有土地上重新造林并为其拨款的法案","en":"An Act Reforesting 3,000 Hectares of Public Land in Cagayan De Oro City and Appropriating Funds Therefor","orig":"An Act Reforesting 3,000 Hectares of Public Land in Cagayan De Oro City and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 10452","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-04-08","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10452_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8904-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy. – It is the declared policy of the State to protect the people and the environment from flashfloods through reforestation."}},{"id":"PH-H8904-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Reforestation in Cagayan de Oro City. – An area of 3.000 hectares of public land in Cagayan de Oro City as identified by the Department of Environment and Natural Resources shall be reforested."}},{"id":"PH-H8904-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. – The Secretary of Environment and Natural Resources shall immediately include in the Department’s program the implementation of this Act, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8904-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementing Rules and Regulations. – The Department of Environment and Natural Resources shall promulgate the rules and regulations for the effective enforcement of the provisions of this Act."}},{"id":"PH-H8904-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Separability Clause. – Should any provision of this Act or any part thereof be declared invalid, the other provisions, insofar as they are separable from the invalid ones, shall remain in full force and effect."}},{"id":"PH-H8904-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Repealing Clause. – All laws, orders, issuances, rules and regulations or parts thereof inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H8904-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its complete publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p126","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reforesting 3,000 Hectares of Public Land in Cagayan De Oro City and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8905"] = {"id":"PH-H8905","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10453_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将伊洛伊洛市市区Rizal街改设为国道并为此拨款的法案","en":"An Act Converting the Rizal Street in City Proper, Iloilo City into a National Road and Appropriating Funds Therefor","orig":"An Act Converting the Rizal Street in City Proper, Iloilo City into a National Road and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10453","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-04-08","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10453_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8905-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Rizal Street in City Proper, Iloilo City is hereby converted into a national road under the supervision of the Department of Public Works and Highways."}},{"id":"PH-H8905-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Public Works and Highways shall include in the Department’s program the improvement, repair and maintenance of the said road, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8905-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in a newspaper of general circulation."}}],"pack":"ph-p126","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Rizal Street in City Proper, Iloilo City into a National Road and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
